import json
from pathlib import Path
import numpy as np
from .contracts import DiagnosticError


def render(path,group,corr,plant,weather,summary,scored,cfg):
    if len(group)>cfg['maximum_dashboard_group_rows']:raise DiagnosticError('Dashboard row budget exceeded; partition periods explicitly.')
    g=group.copy();g['hour']=g.ts.dt.hour;g['month']=g.ts.dt.month;g['date']=g.ts.dt.strftime('%Y-%m-%d')
    g['absolute_error']=g.error_kwh.abs();g['ts']=g.ts.map(lambda t:t.isoformat())
    # Plant means for inspection/histogram; all-hours raw residual distributions remain in source summaries.
    p=plant.groupby(['model_id','forecast_round','validation_fold','site_id']).agg(mean_error=('error_kwh','mean'),mae=('error_kwh',lambda v:v.abs().mean())).reset_index()
    w=[]
    if weather is not None:
        q=weather.groupby(['model_id','forecast_round','validation_fold','ts']).agg(irradiance=('irradiance','mean'),absolute_error=('error_kwh',lambda v:v.abs().mean())).reset_index() if 'irradiance' in weather else None
        if q is not None:q['ts']=q.ts.map(lambda t:t.isoformat());w=json.loads(q.to_json(orient='records'))
    scored_rows=[]
    if scored is not None:
        s=scored.copy();s['ts']=s.ts.map(lambda t:t.isoformat());scored_rows=json.loads(s.to_json(orient='records'))
    payload={'groups':json.loads(g.to_json(orient='records')),'corr':json.loads(corr.to_json(orient='records')),
        'plants':json.loads(p.to_json(orient='records')),'weather':w,'summary':json.loads(summary.to_json(orient='records')),
        'penalty':scored_rows}
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><title>SYNTHETIC error analysis</title>
<style>body{font:15px system-ui;margin:24px;color:#17212b}canvas{width:100%;height:260px;border:1px solid #aaa}section{margin:18px 0;min-width:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(400px,1fr));gap:16px}select,input,button{padding:6px;margin:3px}pre{white-space:pre-wrap}.scroll{overflow:auto}td,th{border:1px solid #ccc;padding:6px}table{border-collapse:collapse}</style>
<h1>SYNTHETIC diagnostic dashboard</h1><p>Diagnostic associations only. No real competition evidence or corrections. Blue=actual/error, orange=forecast. Positive errors mean overprediction.</p>
<div id="controls"></div><label>From <input id="from" type="date"></label><label>Through <input id="through" type="date"></label><label>Hour <select id="hour"><option value="all">All</option></select></label><label>Weather irradiance minimum (W/m2, synthetic) <input id="weather_min" type="number" value="0"></label>
<label>Metric <select id="metric"><option value="absolute_error">Absolute error kWh</option><option value="error_kwh">Signed error kWh</option><option value="cancellation_kwh">Cancellation kWh</option></select></label><label>Plant inspection <select id="plant"></select></label><button id="png">PNG of actual/forecast</button><button id="html">Export HTML</button><p id="coverage"></p><pre id="inspect"></pre>
<div class="grid"><section><h2>1 Actual versus forecast (kWh)</h2><canvas id="actual"></canvas></section><section><h2>2 Signed error over time (kWh)</h2><canvas id="signed"></canvas></section><section><h2>3 Mean selected metric by hour</h2><canvas id="hourly"></canvas></section><section><h2>4 Monthly signed-error quantiles (10%,50%,90%)</h2><canvas id="monthly"></canvas></section><section><h2>5 Signed group error histogram (counts)</h2><canvas id="histogram"></canvas></section><section><h2>6 Weather versus mean plant absolute error</h2><canvas id="weather"></canvas></section><section><h2>7 Within-group error correlations</h2><canvas id="matrix"></canvas><p>Full saved fold, not date-filtered; gray=undefined. CSV retains exact plant IDs and pair counts.</p></section><section><h2>8 Cancellation versus uncancelled error (kWh)</h2><canvas id="cancel"></canvas></section><section><h2>9 Penalty month-hour heatmap</h2><canvas id="penalty"></canvas></section><section><h2>12 Penalty concentration</h2><canvas id="concentration"></canvas></section></div>
<section><h2>10–11 Model and grouping comparison</h2><p>Full saved folds. This table does not follow date/weather/hour filters; compare within identical fold, round and grouping.</p><div class="scroll" id="comparison"></div></section>
<script>const D=__DATA__;
function sel(id,values){const s=document.createElement('select');s.id=id;values.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=id+': '+v;s.append(o)});document.getElementById('controls').append(s);return s}
for(const id of ['model_id','grouping_id','group','forecast_round','validation_fold'])sel(id,[...new Set(D.groups.map(r=>r[id]))]);
for(let i=0;i<24;i++){const o=document.createElement('option');o.value=i;o.textContent=i;document.getElementById('hour').append(o)}
for(const id of [...new Set(D.plants.map(r=>r.site_id))]){const o=document.createElement('option');o.textContent=id;document.getElementById('plant').append(o)}
const dates=D.groups.map(r=>r.date).sort();document.getElementById('from').value=dates[0];document.getElementById('through').value=dates[dates.length-1];
function context(id){const e=document.getElementById(id);e.width=1000;e.height=280;const x=e.getContext('2d');x.fillStyle='white';x.fillRect(0,0,1000,280);x.font='12px sans-serif';return x}
function message(id,msg){const x=context(id);x.fillStyle='#333';x.fillText(msg,20,80)}
function chart(id,series,labels){const vals=series.flat().filter(v=>v!==null&&Number.isFinite(v));if(!vals.length){message(id,'Unavailable / insufficient observations');return}const x=context(id),lo=Math.min(0,...vals),hi=Math.max(0,...vals),span=hi-lo||1,n=Math.max(...series.map(v=>v.length));x.fillStyle='#222';x.fillText('min '+lo.toPrecision(4)+' / max '+hi.toPrecision(4),10,15);series.forEach((s,k)=>{x.strokeStyle=['#2563eb','#d97706','#7c3aed'][k%3];let prev=false;x.beginPath();s.forEach((v,i)=>{if(v===null||!Number.isFinite(v)){prev=false;return}const a=45+i*920/Math.max(1,n-1),b=245-(v-lo)/span*210;if(prev)x.lineTo(a,b);else x.moveTo(a,b);prev=true});x.stroke()});x.fillText(String(labels[0]??''),40,275);x.fillText(String(labels[labels.length-1]??''),780,275)}
function mean(v){return v.length?v.reduce((a,b)=>a+b,0)/v.length:null}function q(v,p){v=v.slice().sort((a,b)=>a-b);if(!v.length)return null;const i=(v.length-1)*p,l=Math.floor(i),h=Math.ceil(i);return v[l]+(v[h]-v[l])*(i-l)}
function match(r,keys){return keys.every(k=>r[k]===document.getElementById(k).value)}
function heat(id,rows,columns,value){if(!rows.length){message(id,'Unavailable: no verified SMP / matrix observations');return}const x=context(id),a=[...new Set(rows.map(r=>r[columns[0]]))],b=[...new Set(rows.map(r=>r[columns[1]]))];for(const r of rows){const v=r[value],i=a.indexOf(r[columns[0]]),j=b.indexOf(r[columns[1]]);x.fillStyle=v===null?'#bbb':`hsl(${v<0?25:215} 65% ${95-Math.min(1,Math.abs(v))*55}%)`;x.fillRect(50+j*900/b.length,25+i*210/a.length,900/b.length+1,210/a.length+1)}x.fillStyle='#222';x.fillText(columns.join(' / ')+'; IDs/cell values in CSV',30,265)}
function render(){const keys=['model_id','grouping_id','group','forecast_round','validation_fold'],hour=document.getElementById('hour').value,threshold=Number(document.getElementById('weather_min').value),weather=D.weather.filter(r=>match(r,['model_id','forecast_round','validation_fold'])),wm=new Map(weather.map(r=>[r.ts,r.irradiance]));let f=D.groups.filter(r=>match(r,keys)&&r.date>=document.getElementById('from').value&&r.date<=document.getElementById('through').value&&(hour==='all'||r.hour===Number(hour))&&(threshold<=0||(wm.has(r.ts)&&wm.get(r.ts)>=threshold))).sort((a,b)=>a.ts.localeCompare(b.ts));document.getElementById('coverage').textContent=f.filter(r=>r.error_kwh!==null).length+' valid / '+f.length+' selected group-hours. Weather filtering uses whole-portfolio mean, not group-specific meteorology.';chart('actual',[f.map(r=>r.actual_kwh),f.map(r=>r.forecast_kwh)],f.map(r=>r.ts));chart('signed',[f.map(r=>r.error_kwh)],f.map(r=>r.ts));const metric=document.getElementById('metric').value;chart('hourly',[[...Array(24).keys()].map(h=>mean(f.filter(r=>r.hour===h&&r[metric]!==null).map(r=>r[metric])))],[0,23]);const months=[...new Set(f.map(r=>r.month))].sort((a,b)=>a-b);chart('monthly',[.1,.5,.9].map(p=>months.map(m=>q(f.filter(r=>r.month===m&&r.error_kwh!==null).map(r=>r.error_kwh),p))),months);const values=f.map(r=>r.error_kwh).filter(v=>v!==null);if(values.length){const lo=Math.min(...values),hi=Math.max(...values),bins=Array(20).fill(0);values.forEach(v=>bins[Math.min(19,Math.floor((v-lo)/(hi-lo||1)*20))]++);chart('histogram',[bins],[lo.toPrecision(4),hi.toPrecision(4)])}else message('histogram','No observations');const times=new Set(f.map(r=>r.ts)),w=weather.filter(r=>times.has(r.ts)).sort((a,b)=>a.irradiance-b.irradiance);chart('weather',[w.map(r=>r.absolute_error)],w.map(r=>r.irradiance));chart('cancel',[f.map(r=>r.cancellation_kwh),f.map(r=>r.absolute_error)],f.map(r=>r.ts));heat('matrix',D.corr.filter(r=>match(r,['model_id','grouping_id','group','forecast_round','validation_fold'])),['site_i','site_j'],'correlation');const penalty=D.penalty.filter(r=>match(r,keys)&&times.has(r.ts));if(penalty.length){const cells={};penalty.forEach(r=>{const k=r.ts.slice(5,7)+'-'+r.ts.slice(11,13);(cells[k]??=[]).push(r.penalty)});const list=Object.entries(cells).map(([k,v])=>({month:k.split('-')[0],hour:k.split('-')[1],value:mean(v)})),mx=Math.max(1,...list.map(r=>Math.abs(r.value)));heat('penalty',list.map(r=>({...r,value:r.value/mx})),['month','hour'],'value');const v=penalty.map(r=>r.penalty).filter(v=>v!==null).sort((a,b)=>b-a),total=v.reduce((a,b)=>a+b,0);let sum=0;chart('concentration',[v.map(x=>(sum+=x)/total)],[0,1])}else{message('penalty','Unavailable: no verified SMP supplied');message('concentration','Unavailable: no verified SMP supplied')}document.getElementById('inspect').textContent=JSON.stringify(D.plants.filter(r=>match(r,['model_id','forecast_round','validation_fold'])&&r.site_id===document.getElementById('plant').value),null,2)+'\nPlant inspection uses full saved fold, not group filters.'}
const table=document.createElement('table'),keys=['model_id','grouping_id','group','forecast_round','validation_fold','sample_count','expected_count','me','mae','rmse'];const head=document.createElement('tr');keys.forEach(k=>{const h=document.createElement('th');h.textContent=k;head.append(h)});table.append(head);D.summary.forEach(r=>{const tr=document.createElement('tr');keys.forEach(k=>{const td=document.createElement('td');td.textContent=r[k]===null?'unavailable':String(r[k]);tr.append(td)});table.append(tr)});document.getElementById('comparison').append(table);
for(const e of document.querySelectorAll('select,input'))e.addEventListener('change',render);document.getElementById('png').onclick=()=>{const a=document.createElement('a');a.href=document.getElementById('actual').toDataURL('image/png');a.download='synthetic_error_analysis.png';a.click()};document.getElementById('html').onclick=()=>{const u=URL.createObjectURL(new Blob(['<!doctype html>'+document.documentElement.outerHTML],{type:'text/html'})),a=document.createElement('a');a.href=u;a.download='synthetic_error_dashboard.html';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};render();</script></html>'''
    Path(path).write_text(html.replace('__DATA__',json.dumps(payload,allow_nan=False).replace('<','\\u003c')),encoding='utf-8')
